I got a very hacky solution by using Bun's react rendering

```jsx
import { renderToReadableStream } from "react-dom/server";

const Component = () => {
  return (<div>hi</div>)
}

app.get('/sse', async (c) => {
    return streamSSE(c, async (stream) => {
        while (true) {
            await stream.writeSSE({
                data: await Bun.readableStreamToText(await renderToReadableStream(<Component />)),
                id: String(id++),
            })
            await stream.sleep(1000)
        }
    })
})
```

